/**
 * The `info` / `GET /v1/info` projection of an {@link AgentProject}.
 */
import { resolveArtifactsMax } from "../../artifacts.js";
import { toPublicCloudInfo } from "../../types.js";
import { toolInputJsonSchema } from "../json-schema.js";
import { MCP_ENDPOINT_PATH, mcpEndpointToolNames } from "../mcp-endpoint.js";
import { DEFAULT_AGENT_ARCHITECTURE } from "./agent-config.js";
import { connectionTransportLabel } from "./connections.js";
export function projectInfo(project) {
    const agent = project.agent;
    const httpRoutes = [
        { method: "POST", path: "/v1/session", url: "/v1/session" },
        {
            method: "POST",
            path: "/v1/session/:sessionId",
            url: "/v1/session/:sessionId",
        },
        {
            method: "POST",
            path: "/v1/session/:sessionId/stop",
            url: "/v1/session/:sessionId/stop",
        },
        {
            method: "GET",
            path: "/v1/session/:sessionId/stream",
            url: "/v1/session/:sessionId/stream",
        },
        {
            method: "GET",
            path: "/v1/session/:sessionId/approvals",
            url: "/v1/session/:sessionId/approvals",
        },
        {
            method: "POST",
            path: "/v1/session/:sessionId/approvals/:callId",
            url: "/v1/session/:sessionId/approvals/:callId",
        },
    ];
    return {
        schemaVersion: 1,
        name: project.name,
        description: agent.description,
        model: agent.model,
        architecture: agent.architecture ?? DEFAULT_AGENT_ARCHITECTURE,
        runtime: agent.runtime,
        cloud: agent.cloud === undefined ? undefined : toPublicCloudInfo(agent.cloud),
        local: agent.local?.cwd === undefined ? undefined : { cwd: agent.local.cwd },
        hosting: agent.hosting,
        concurrency: agent.concurrency,
        mcp: { path: MCP_ENDPOINT_PATH, tools: mcpEndpointToolNames(project) },
        instructions: agent.instructions === undefined
            ? undefined
            : {
                chars: agent.instructions.length,
                preview: agent.instructions.length > 280
                    ? `${agent.instructions.slice(0, 277)}...`
                    : agent.instructions,
            },
        tools: agent.tools.map((tool) => ({
            name: tool.name,
            description: tool.description,
            execution: tool.execution,
            needsApproval: typeof tool.definition.needsApproval === "function" ? "dynamic" : tool.needsApproval,
            effect: tool.effect,
            inputSchema: tool.inputSchema,
        })),
        skills: agent.skills.map((skill) => ({
            name: skill.name,
            description: skill.description,
        })),
        extensions: agent.extensions ?? [],
        connections: agent.connections.map((connection) => ({
            name: connection.name,
            transport: connectionTransportLabel(connection.transport),
            advertiseTools: connection.advertiseTools,
            optional: connection.optional,
            effects: connection.effects,
            tools: connection.tools,
            disallowedTools: connection.disallowedTools,
            cursorAccountServers: "cursorAccount" in connection.transport ? (connection.transport.servers ?? "*") : undefined,
        })),
        subagents: agent.subagents.map((subagent) => ({
            name: subagent.name,
            description: subagent.description,
            model: subagent.model,
        })),
        channels: [
            { id: "http", routes: httpRoutes },
            ...project.channels.map((channel) => {
                const info = {
                    id: channel.id,
                    routes: (channel.definition.routes ?? []).map((r) => {
                        const routeInfo = {
                            method: r.method,
                            path: r.path,
                            url: `/v1/channels/${channel.id}${r.path}`,
                        };
                        if (r.description !== undefined) {
                            routeInfo.description = r.description;
                        }
                        if (r.bodySchema !== undefined) {
                            routeInfo.bodySchema = toolInputJsonSchema(r.bodySchema);
                        }
                        if (r.querySchema !== undefined) {
                            routeInfo.querySchema = toolInputJsonSchema(r.querySchema);
                        }
                        return routeInfo;
                    }),
                };
                const meta = channel.definition.meta;
                if (meta?.kind !== undefined) {
                    info.kind = meta.kind;
                }
                if (meta?.githubWebhookEvents !== undefined) {
                    info.githubWebhookEvents = meta.githubWebhookEvents;
                }
                if (meta?.originWebhookEvents !== undefined) {
                    info.originWebhookEvents = meta.originWebhookEvents;
                }
                if (meta?.gitlabWebhookEvents !== undefined) {
                    info.gitlabWebhookEvents = meta.gitlabWebhookEvents;
                }
                if (meta?.bitbucketWebhookEvents !== undefined) {
                    info.bitbucketWebhookEvents = meta.bitbucketWebhookEvents;
                }
                if (meta?.pagerdutyWebhookEvents !== undefined) {
                    info.pagerdutyWebhookEvents = meta.pagerdutyWebhookEvents;
                }
                if (meta?.deploymentEventTypes !== undefined) {
                    info.deploymentEventTypes = meta.deploymentEventTypes;
                }
                if (meta?.slackEventTypes !== undefined) {
                    info.slackEventTypes = meta.slackEventTypes;
                }
                if (meta?.slackChannelPosts !== undefined) {
                    info.slackChannelPosts = meta.slackChannelPosts;
                }
                return info;
            }),
        ],
        schedules: project.schedules.map((schedule) => ({
            name: schedule.name,
            cron: schedule.cron,
            kind: schedule.kind,
        })),
        reminders: (project.reminders ?? []).length === 0
            ? undefined
            : (project.reminders ?? []).map((reminder) => ({
                name: reminder.name,
            })),
        hooks: project.hooks.map((hook) => hook.name),
        storage: project.storage === undefined ? undefined : { name: project.storage.name },
        artifacts: project.artifacts === undefined
            ? undefined
            : {
                kinds: Object.keys(project.artifacts.kinds ?? {}),
                agentTool: project.artifacts.agentTool === true,
                max: resolveArtifactsMax(project.artifacts),
            },
        diagnostics: project.diagnostics.map((diagnostic) => ({ ...diagnostic })),
    };
}
